'use strict';

// MODULES //

var expit = require( '@stdlib/math/base/special/expit' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var NINF = require( '@stdlib/constants/float64/ninf' );


// VARIABLES //

/**
* Square root of `2` divided by `π`.
*
* \sqrt{\frac{2}{\pi}}
*/
var SQRT_TWO_DIVIDED_BY_PI = 0.7978845608028654;


// MAIN //

/**
* Evaluates the Gaussian Error Linear Unit (GELU) activation function using a tanh approximation.
*
* @param {number} x - input value
* @returns {number} function value
*
* @example
* var v = tanh( 0.0 );
* // returns 0.0
*
* @example
* var v = tanh( 1.0 );
* // returns ~0.8412
*
* @example
* var v = tanh( -Infinity );
* // returns -0.0
*
* @example
* var v = tanh( Infinity );
* // returns Infinity
*
* @example
* var v = tanh( NaN );
* // returns NaN
*/
function tanh( x ) {
	var z;
	if ( isnan( x ) ) {
		return NaN;
	}
	if ( x === NINF ) {
		return -0.0;
	}
	z = SQRT_TWO_DIVIDED_BY_PI * ( x + ( 0.044715 * x * x * x ) );
	return x * expit( 2.0 * z );
}


// EXPORTS //

module.exports = tanh;
